	hidden_effect = {
		if = {
			limit = {
				root.faith = faith:christian_faith
				pam_schism_county_rite_in_pair_trigger = { COUNTY = scope:selected_item.holy_site_county }
			}
			pam_change_great_schism_progress_effect = {
				VALUE = pam_great_schism_progress_holy_site_value
				TT = pam_great_schism_progress_holy_site_tt
			}
		}
	}

# Scope: holy_site
# Returns: the sum of Artifact Rarity values of every artifact enshrined in
# the holy site whose is_holy_relic trigger passes for the controlling faith.
# (And the controlling faith also has this holy site as one of their own)
# Each artifact contributes 1=Common, 2=Masterwork, 3=Famed, 4=Illustrious.
# 0 if nothing qualifies.
# Backed by the `total_active_artifact_rarity_sum` trigger registered in
# holy_site_artifact_trigger_impl.cpp.
holy_site_total_artifact_rarity = {
	value = root.total_active_artifact_rarity_sum
}

# How long a ruler must wait between holy site actions, shared by the decisions and by holy site creation.
holy_site_action_cooldown_years = {
	value = 5
}

# Scope: character taking one of the holy site decisions.
# Cooldown in years, waived while the faith still has a free holy site action left. Decision cooldowns
# are evaluated with only the taking character in scope - no saved scopes - so this can read the faith
# but nothing about the selected holy site.
holy_site_decision_cooldown_value = {
	value = holy_site_action_cooldown_years
	if = {
		limit = { faith = { faith_has_free_holy_site_action_trigger = yes } }
		value = 0
	}

holy_site_elevated_county_holder_opinion = {
	opinion = 50
	decaying = yes
	years = 10
}

# Demoted my [holy_site|E] county
holy_site_demoted_county_holder_opinion = {
	opinion = -50
	decaying = yes
	years = 10
}

holy_site_elevated_modifier = {
	icon = piety_positive
	zealot_same_faith_opinion = 30
}

holy_site_demoted_modifier = {
	icon = piety_negative
	zealot_same_faith_opinion = -20
	parochial_same_faith_opinion = -20
}

faith_has_free_holy_site_action_trigger = {
	trigger_if = {
		limit = { has_variable = free_holy_site_actions }
		var:free_holy_site_actions >= 1
	}
	trigger_else = {
		always = no
	}
}

# After the cost is already waived, a decision effect runs this on the faith
consume_free_holy_site_action_effect = {
	if = {
		limit = { faith_has_free_holy_site_action_trigger = yes }
		change_variable = {
			name = free_holy_site_actions
			subtract = 1
		}
	}
}
